        cat: "mindset",
        cat_zh: "🧠 冠軍心態",
        avatar: "🧘‍♂️",
        takeaway: "比賽突遇大暴雨或大掉速時，不要驚慌哀嘆；告訴自己大家都面臨同樣的折磨，誰心態先崩誰就輸，這正是超車的大好機會！"
