        athlete_en: "Eliud Kipchoge",
        athlete_zh: "埃利烏德·基普喬蓋",
        title: "肯亞馬拉松哲人王",
        cat: "discipline",
        cat_zh: "🛡️ 極致自律",
        avatar: "🙏",
        takeaway: "不要把精力浪費在尋找速成偏方上；十點就寢、保證深層睡眠、健康原型食物、規律有氧，大道至簡，唯在執行。"
